import {Game,CONFIG,TYPES,TYPE,info,SUITS,COLORS,MATERIALS,baseCap,cap,usage,owned,dimensions,score,recommend,nextDora,TRAIT_CATALOG,TRAIT_REWARDS,tileTier,buyPrice,sellPrice,arrangeShowcase,SHOP_REFRESH_COST,jadeMultiplier} from './game.js?v=0.13.0';
import {LocalAccounts} from './local-accounts.js';
import {mountLocalAccountUI} from './local-account-ui.js';
const appScope=new URL('./',document.baseURI).pathname;
let accountStorage;
try{accountStorage=window.localStorage;}catch{accountStorage={getItem(){throw Error('此浏览器禁止网站存储，请允许后刷新。');},setItem(){throw Error('无法保存');},removeItem(){throw Error('无法保存');}};}
const account=new LocalAccounts({storage:accountStorage,validate:raw=>Game.restore(raw),scope:appScope});

let accountUI;
let game;try{const saved=account.localSnapshot();game=saved?Game.restore(saved):new Game();}catch{game=new Game();}
const ui={modal:null,discard:new Set(),muted:true,shopHidden:false,round:game.round,traitsExpanded:false,scoring:null,push:null};
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{account.capture(game.export());}catch{toast('当前进度未能保存，请导出账号备份。');}}
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function sound(){if(ui.muted)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),gain=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(620,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(340,ctx.currentTime+.07);gain.gain.setValueAtTime(.04,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.connect(gain);gain.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.13);o.onended=()=>ctx.close();}catch{}}
const number=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:3,notation:Math.abs(n)>=1e6?'compact':'standard'}).format(n);
const wildSummary=r=>r.wildCopies?.length?r.wildCopies.map(c=>'中→'+info(c.face).name).join(' · '):r.wild?'中→'+info(r.wild).name:'';
const displayScoreTile=(t,r)=>{const copy=r.wildCopies?.find(c=>c.uid===t.uid);return copy?{...t,face:copy.face}:t;};
function showcaseMarkup(r,mode='score'){
 return arrangeShowcase(r.tiles,r).map(g=>'<span class="showcase-group group-'+g.phase+'" data-showcase-kind="'+g.kind+'" data-showcase-phase="'+g.phase+'">'+g.tiles.map(t=>mode==='score'?'<span class="score-tile '+(g.phase==='spare'?'unscored':'valid')+'" data-score-uid="'+t.uid+'">'+face(displayScoreTile(t,r))+'<small>'+g.kind+'</small></span>':face(displayScoreTile(t,r),mode==='result'?'mini':'')).join('')+'</span>').join('');
}
const glyph=n=>['','一','二','三','四','五','六','七','八','九'][n];
function artwork(face,color){
 const d=info(face),ink=color==='red'?'#b83935':color==='green'?'#27653b':color==='cyan'?'#287681':d.s===1?'#253e61':'#245c3b',red='#b73431',black='#232b29';let body='';
 // LiSu is deliberately local: no redistribution of a system font.
 if(d.s===0)body=`<g font-family="LiSu,隶书,STLiti,serif" text-anchor="middle"><text class="wan-number" x="30" y="34" font-size="29" fill="${black}">${glyph(d.n)}</text><text class="wan-character" x="30" y="69" font-size="32" fill="${red}">萬</text></g>`;
 const ring=(x,y,r,c)=>`<g transform="translate(${x} ${y})" fill="none" stroke="${c}" stroke-width="${r>10?2.4:1.55}"><circle r="${r}"/><circle r="${r*.59}"/><path d="M${-r*.7} 0h${r*1.4}M0 ${-r*.7}v${r*1.4}" stroke-width=".8"/><circle r="${r*.17}" fill="${c}" stroke="none"/></g>`;
 if(d.s===1){let points;
  if(d.n===1)points=[[30,43]];else if(d.n===2)points=[[30,25],[30,61]];else if(d.n===3)points=[[17,23],[30,43],[43,63]];else if(d.n===4)points=[[17,25],[43,25],[17,61],[43,61]];else if(d.n===5)points=[[17,23],[43,23],[30,43],[17,63],[43,63]];else if(d.n===6)points=[[18,21],[42,21],[18,43],[42,43],[18,65],[42,65]];
  else if(d.n===7)points=[[16,18],[30,25],[44,32],[18,49],[42,49],[18,67],[42,67]];
  else if(d.n===8)points=[[18,17],[42,17],[18,34],[42,34],[18,51],[42,51],[18,68],[42,68]];else points=[17,30,43].flatMap(x=>[20,43,66].map(y=>[x,y]));
  const radius=d.n===1?17:d.n>=7?5.4:d.n>=5?6.4:8;
  body=points.map(([x,y],i)=>ring(x,y,radius,color?ink:d.n===7&&i>=3||d.n===5&&i===2||d.n===9&&i>=3&&i<6?red:ink)).join('');
 }
 const bamboo=(x,y,c,angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle})"><path d="M-1.8-7Q0-8 1.8-7L1.4 7Q0 8-1.4 7Z" fill="${c}"/><path d="M-3-6h6M-3 0h6M-3 6h6" stroke="${c}" stroke-width="1.7" stroke-linecap="round"/><path d="M-.4-5v4m0 2v4" stroke="#f8f0d6" stroke-width=".65" opacity=".7"/></g>`;
 if(d.s===2){
  if(d.n===1)body=`<g stroke-linejoin="round"><path d="M19 53C5 48 8 28 19 20c-3 12 1 19 8 21C11 24 21 10 30 12c-4 10-3 19 2 26C24 19 35 13 41 19l-5 20C46 26 51 34 47 43L34 53Z" fill="${ink}"/><path d="M14 27l8 19M24 20l5 23M37 25l-6 22M43 39l-10 10" fill="none" stroke="#f2e5b8" stroke-width="1.1"/><path d="M20 52C17 37 24 27 32 30c8 2 12 15 5 24l-10 4Z" fill="${color?ink:'#b33b35'}"/><path d="M23 47c0-9 7-13 12-7l-5 11Z" fill="#e4c576"/><path d="M35 33c3-4 0-9 3-13 3-4 9-3 10 1l-2 10-8 10" fill="${ink}"/><path d="M47 23l7 3-8 2" fill="#b63d34"/><circle cx="43.8" cy="22" r="1.1" fill="#f5e7b7"/><path d="M27 55l-7 12 7-4 4 8 2-15M37 54l4 11 5 1" fill="none" stroke="${ink}" stroke-width="2.2"/><path d="M12 72h36" stroke="${ink}" stroke-width="1.4"/></g>`;
  else if(d.n===5){body='<g data-bamboo-layout="five-quincunx">'+[[17,22],[43,22],[17,64],[43,64]].map(([x,y])=>bamboo(x,y,ink)).join('')+bamboo(30,43,color?ink:red)+'</g>';}
  else if(d.n===7){body=bamboo(30,17,color?ink:red);for(const y of [37,52,67])for(const x of [17,43])body+=bamboo(x,y,ink);}
  else if(d.n===8){body='<g data-bamboo-layout="eight-m-w">';for(const [x,y,angle] of [[13,25,0],[24,25,40],[36,25,-40],[47,25,0],[13,58,0],[24,58,-40],[36,58,40],[47,58,0]])body+=bamboo(x,y,ink,angle);body+='</g>';}
  else {const cols=d.n<=3?1:d.n<=6?2:3,rows=Math.ceil(d.n/cols);for(let i=0;i<d.n;i++){const x=30+(i%cols-(cols-1)/2)*16,y=19+Math.floor(i/cols)*48/Math.max(1,rows-1);body+=bamboo(x,y,!color&&(d.n===5&&i===4||d.n===9&&i%3===1)?red:ink);}}
 }
 if(d.s===3){if(d.n===6)body='<rect x="14" y="24" width="32" height="36" rx="3" fill="none" stroke="#3e6669" stroke-width="3"/><rect x="20" y="30" width="20" height="24" rx="1" fill="none" stroke="#3e6669"/>';else body=`<text x="30" y="57" font-family="LiSu,隶书,STLiti,serif" font-size="38" text-anchor="middle" fill="${color?ink:d.n===4?red:d.n===5?'#27653b':black}">${d.name}</text>`;}
 if(d.s===4)body=`<path d="M30 13l5 12 13-4-5 13 8 9-13 4-1 15-12-8-10 8 1-15-12-4 10-10-3-12 13 4Z" transform="translate(5 2) scale(.85)" fill="none" stroke="#ad874c" stroke-width="1.2"/><text x="30" y="54" font-family="LiSu,隶书,STLiti,serif" font-size="24" text-anchor="middle" fill="#9b7942">${d.name}</text>`;
 return `<svg viewBox="0 0 60 84" aria-hidden="true">${body}</svg>`;
}
function face(t,size=''){return `<span class="tile-face ${size} ${t.color?'color-'+t.color:''} ${t.material?'mat-'+t.material:''} ${t.pattern?'has-pattern':''} ${dimensions(t)?'special-face':''}" ${tileTipAttributes(t)}>${artwork(t.face,t.color)}${t.color?`<span class="color-mark">${{red:'赤',green:'绿',cyan:'青'}[t.color]}</span>`:''}${t.pattern?`<span class="pattern-overlay" data-pattern-face="${t.pattern}" aria-hidden="true">${artwork(t.pattern,'cyan')}</span>`:''}</span>`;}
function describe(t){return `${info(t).name}${t.color?' · '+COLORS[t.color]:''}${t.pattern?' · '+info(t.pattern).name+'纹路':''}${t.material?' · '+MATERIALS[t.material]+'材质':''}${(t.material==='jade'?jadeMultiplier(t):1)*(t.diamond||1)>1?' · ×'+(t.material==='jade'?jadeMultiplier(t):1)*(t.diamond||1):''}`;}
function tile(t,{mode='hand',selected=false,locked=false}={}){return `<span class="tile-wrap"><button class="tile-button ${selected?(mode==='show'?'chosen':'selected'):''}" data-action="${mode==='show'?'showtile':'handtile'}" data-uid="${t.uid}" aria-label="${esc(describe(t))}${locked?'，副露锁定':''}" aria-pressed="${selected}" ${locked?'disabled':''}>${face(t)}</button><span class="tile-caption">${locked?'副露':t.material?MATERIALS[t.material]:t.pattern?'纹路':t.color?COLORS[t.color]:''}${t.growth*t.diamond>1?' ×'+t.growth*t.diamond:''}</span><button class="tile-detail" data-action="detail" data-uid="${t.uid}" aria-label="查看${esc(info(t).name)}详情">i</button></span>`;}
function playerScore(){const p=game.players[0];return score(game.phase==='showdown'&&!game.preparation?game.displayPool().filter(t=>game.selected.includes(t.uid)):owned(p),p.indicators,game.config,p.melds);}

function synergyPanel(r){
 const tiles=game.phase==='showdown'&&!game.preparation?game.displayPool().filter(t=>game.selected.includes(t.uid)):owned(game.players[0]);
 const regular=r.traits.filter(t=>t.count>0).sort((a,b)=>b.stage-a.stage||b.count-a.count);
 const special=[{name:'赖子',icon:'中',count:tiles.filter(t=>t.face==='h-4').length,need:3,detail:'三张红中，复制左邻牌面'},{name:'捉鸡',icon:'雀',count:r.chicken,need:2,detail:'一索与八筒合计两张激活'},{name:'宝牌',icon:'宝',count:tiles.filter(t=>t.color==='red').length,need:2,detail:'两张红宝，翻出宝牌指示物'}].filter(t=>t.count>0);
 if(!regular.length&&!special.length)return '';
 const shown=ui.traitsExpanded?regular:regular.slice(0,5);
 return '<aside class="trait-dock" aria-label="当前手牌相关羁绊"><div class="trait-dock-heading"><span>牌势</span><button data-action="catalog" aria-label="查看全部羁绊图鉴">ⓘ</button></div><div class="trait-list">'+shown.map(t=>'<button class="trait-chip '+(t.stage?'active':'')+'" data-action="trait" data-name="'+t.name+'" data-tooltip-trait="'+t.id+'"><span class="trait-icon">'+t.icon+'</span><span class="trait-label">'+t.name+'<span class="trait-bars">'+t.thresholds.map((_,i)=>{const n=i+1;return '<i class="'+(t.stage>=n?'on':'')+'"></i>';}).join('')+'</span></span><span class="trait-count">'+t.count+'<small>/'+(t.thresholds.find(n=>n>t.count)||t.thresholds.at(-1))+'</small></span></button>').join('')+'</div>'+(regular.length>5?'<button class="trait-more" data-action="traits">'+(ui.traitsExpanded?'收起羁绊 ↑':'另有 '+(regular.length-5)+' 个相关羁绊 ↓')+'</button>':'')+(special.length?'<div class="special-traits">'+special.map(t=>'<button class="special-chip '+(t.count>=t.need?'active':'')+'" data-action="help" data-tooltip-special="'+esc(JSON.stringify(t))+'"><span>'+t.icon+'</span>'+t.name+'<b>'+t.count+'/'+t.need+'</b></button>').join('')+'</div>':'')+'</aside>';
}
function opponent(i){const p=game.players[i];return '<button class="seat-badge seat-'+i+'" data-action="opponent" data-player="'+i+'" aria-label="查看'+p.name+'的公开牌区"><span class="avatar avatar-'+i+'">'+p.avatar+'</span><span class="seat-name">'+p.name+'<small>'+p.level+'本 · '+owned(p).length+'张</small></span><span class="seat-score">'+number(p.score)+'<small>分</small></span></button>';}
function opponentHand(i){const p=game.players[i];return '<div class="edge-hand edge-'+i+'" style="--opponent-count:'+Math.max(1,p.hand.length)+'" aria-label="'+p.name+(ui.push?'的展示手牌':'的隐藏手牌')+'"><div class="hidden-tiles">'+(ui.push?showcaseMarkup(ui.push.report.results[i],'result'):p.hand.map(()=>'<span class="tile-back" aria-hidden="true"></span>').join(''))+'</div>'+(p.melds.length?'<div class="edge-melds">'+p.melds.map(m=>'<div class="edge-meld">'+m.tiles.map(t=>face(t,'mini')).join('')+'</div>').join('')+'</div>':'')+'</div>';}
function river(i,position){const p=game.players[i],selectable=i===0&&game.phase==='showdown'&&game.preparation?.stage==='select',incoming=game.presentation?.kind==='discard'&&game.presentation.i===i?p.hand.find(t=>t.uid===game.presentation.uid):null;return '<section class="river-area '+position+'" aria-label="'+p.name+'的牌河，共'+p.river.length+'张"><div class="river-grid">'+p.river.map(t=>'<button data-action="'+(selectable?'take-river':'detail')+'" class="'+(selectable?'river-pickable':'')+'" data-uid="'+t.uid+'" data-river-uid="'+t.uid+'" aria-label="'+esc(describe(t))+'">'+face(t,'mini')+'</button>').join('')+(incoming?'<span class="river-slot" data-landing-uid="'+incoming.uid+'">'+face(incoming,'mini')+'</span>':'')+'</div></section>';}
function wall(){const count=game.public.length,stacks=Math.ceil(count/2);let used=0;return '<button class="wall-info" data-action="pools" aria-label="查看公共和个人牌池">'+['north','east','south','west'].map((side,i)=>{const n=Math.floor(stacks/4)+(i<stacks%4?1:0);let body='';for(let k=0;k<n;k++){const double=used*2+1<count;used++;body+='<span class="wall-stack '+(double?'double':'single')+'"></span>';}return '<span class="tile-wall wall-'+side+'">'+body+'</span>';}).join('')+'</button>';}
function board(){const p=game.players[0],active=game.pending?'鸣牌响应':game.presentation?game.players[game.presentation.i].name+(game.presentation.kind==='prepare'?'取牌':'出牌'):({shop:'你的回合',showdown:game.preparation?.stage==='select'?'取牌与出牌':'对决开始',trim:'整理手牌',draft:'做局选牌',over:'本局结束',result:'对决结算'})[game.phase]||'轮流行动';return '<div class="cloth"><div class="table-lines"></div><div class="cloth-emblem">雀</div>'+wall()+[1,2,3].map(opponentHand).join('')+[1,2,3].map(opponent).join('')+river(2,'north')+river(1,'east')+river(3,'west')+river(0,'south')+'<div class="table-center"><span class="center-wind north">西</span><span class="center-wind east">南</span><span class="center-wind west">北</span><span class="center-wind south">东</span><div class="round-display"><span class="center-state">'+active+'</span><strong>'+String(game.round).padStart(2,'0')+'<small> / 24</small></strong><span class="center-showdown">第 '+Math.min(8,Math.ceil(game.round/3))+' / 8 次比拼</span><span class="round-dots">'+[1,2,3].map(n=>'<i class="'+(n<=(game.round-1)%3+1?'on':'')+'"></i>').join('')+'</span></div></div><button class="wall-count" data-action="pools" title="点击查看牌源">牌山 '+game.public.length+(p.packs.length?' · 私池 '+p.pool.length:'')+'</button>'+(p.indicators.length?'<button class="dora-row" data-action="help" aria-label="宝牌指示物"><span>宝</span>'+p.indicators.map(f=>face({face:f},'mini')).join('')+'</button>':'')+'</div>';}
function claimDock(){const q=game.pending;if(q?.options[0]?.to!==0)return '';const opts=q.options.filter(o=>o.to===0);return '<section class="claim-dock" role="region" aria-label="鸣牌选择"><div class="claim-context">'+game.players[q.from].name+'打出 '+info(q.tile).name+'</div><div class="claim-actions">'+opts.map((o,i)=>'<button class="call-button" data-action="claim" data-index="'+i+'" aria-label="'+o.kind+' '+o.tiles.map(t=>info(t).name).join('、')+'"><strong>'+o.kind+'</strong><span class="call-preview">'+o.tiles.map(t=>face(t,'mini')).join('')+'</span></button>').join('')+'<button class="call-cancel" data-action="claim" data-index="-1">取消</button></div></section>';}
function hand(){const p=game.players[0],needs=Math.max(0,usage(p)-cap(p)),phase=game.phase;const actionLabel=({shop:'结束购买',trim:'确认弃牌',showdown:game.preparation?.stage==='select'?'配牌完成 · 出牌':'等待配牌',draft:'做局选牌',over:'最终排名',resolving:'依次出牌'})[phase]||'对决结算';return '<section class="hand-zone" style="--hand-count:'+Math.max(1,owned(p).length)+'" aria-label="你的手牌">'+claimDock()+'<div class="hand-command-bar"><div class="self-info"><span class="avatar">雀</span><strong>你</strong><span class="self-score">'+number(p.score)+'<small>分</small></span><span class="hand-capacity '+(needs?'over':'')+'">'+usage(p)+' / '+cap(p)+' · '+p.level+'本</span></div><div class="hand-tools"><button data-action="sort" '+(!canReorder()?'disabled':'')+' title="按牌面排序">排序</button><button class="primary main-action" data-action="main" '+(!(['shop','trim'].includes(phase)||phase==='showdown'&&game.preparation?.stage==='select')||game.pending||ui.push?'disabled':'')+'>'+actionLabel+' <span>→</span></button></div></div><div class="hand-tiles">'+(p.hand.length?(ui.push?showcaseMarkup(ui.push.report.results[0],'table'):p.hand.map(t=>tile(t,{selected:ui.discard.has(t.uid)})).join('')):'<div class="hand-empty">从商店领取你的第一张牌</div>')+(p.melds.length?'<div class="melds">'+p.melds.map(m=>'<span class="meld-group" data-kind="'+m.kind+'">'+m.tiles.map(t=>tile(t,{locked:true})).join('')+'</span>').join('')+'</div>':'')+'</div></section>';}

function market(){const p=game.players[0],enabled=game.phase==='shop';if(!enabled)return '';if(ui.shopHidden)return '<button class="shop-peek" data-action="shop-toggle" aria-expanded="false">显示商店 <span>◉ '+p.gold+' G</span> ⌄</button>';return '<section class="shop-overlay" aria-label="摸牌商店"><div class="shop-topline"><div class="shop-title"><b>摸牌商店</b><span>首张免费 · 已购 '+p.buys+'/3</span></div><div class="shop-wallet">◉ '+p.gold+' <small>G</small></div><button class="shop-toggle" data-action="shop-toggle" aria-expanded="true">隐藏商店 ⌃</button></div><div class="offers">'+Array.from({length:5},(_,j)=>{const t=p.shop[j];if(!t)return '<div class="offer sold"><span class="sold-symbol">'+(j<p.buys?'✓':'◇')+'</span><span>已购入 / 暂无牌</span></div>';const cost=p.buys?buyPrice(t):0;return '<button class="offer rarity-'+tileTier(t)+(dimensions(t)?' offer-special':'')+(t.color?' offer-'+t.color:'')+(t.material?' offer-'+t.material:'')+(t.pattern?' offer-pattern':'')+'" data-action="buy" data-index="'+j+'" '+(p.buys>=3||p.gold<cost?'disabled':'')+' aria-label="购买'+esc(describe(t))+'，'+(cost?cost+'金币':'免费')+'"><span class="offer-rarity">'+['','白','蓝','紫','橙'][tileTier(t)]+' · '+buyPrice(t)+'G</span><span class="offer-source">'+(t.origin==='public'?'公共牌山':'个人做局')+'</span>'+face(t,'large')+'<span class="offer-name">'+info(t).name+'</span><span class="offer-tags">'+([t.color&&COLORS[t.color],t.pattern&&info(t.pattern).name+'纹',t.material&&MATERIALS[t.material]].filter(Boolean).map(s=>'<i>'+s+'</i>').join('')||'<i>常规牌</i>')+'</span><span class="offer-resale">售出 '+sellPrice(t)+'G</span><span class="offer-price '+(!cost?'free':'')+'">'+(cost?'◉ '+cost+' G':'免费领取 ＋')+'</span></button>';}).join('')+'</div><div class="shop-footer"><span>'+p.level+'本 · 容量 '+cap(p)+'</span><button class="refresh-btn" data-action="refresh-shop" '+(p.gold<SHOP_REFRESH_COST||p.buys>=game.config.maxBuy?'disabled':'')+' title="退回未购买的牌，重新抽5张；购买次数和首张免费状态保留">换牌 · '+SHOP_REFRESH_COST+'G ↻</button><button class="upgrade-btn" data-action="upgrade" '+(p.level===4||p.gold<game.config.upgrade[p.level]?'disabled':'')+' title="容量＋3，下次换牌或下回合提高牌面等级与异色率">'+(p.level===4?'已达四本':'升至'+glyph(p.level+1)+'本 · '+game.config.upgrade[p.level]+'G ↗')+'</button><button class="shop-info" data-action="pools">牌源与异色 ⓘ</button></div></section>';}
function catalog(name){const all=TRAIT_CATALOG.filter(t=>!name||t.name===name);const r=playerScore();return modal('<h2 class="modal-title">'+(name||'羁绊图鉴')+'</h2><p class="modal-sub">17种常规羁绊 · 按各自组件门槛逐档增强<br>同一实体在同一羁绊中只计一次；颜色、纹路与材质的身份各有用途。</p><div class="catalog-grid">'+all.map(t=>{const current=r.traits.find(x=>x.name===t.name);return '<article class="catalog-entry"><span class="catalog-icon">'+t.icon+'</span><div><h3>'+t.name+'<small>'+(current?.count||0)+' 张组件</small></h3><p>'+esc(t.rule||t.detail)+'</p><p class="catalog-thresholds">档位 '+t.thresholds.join(' / ')+' 张</p>'+(t.source?'<a class="catalog-origin" href="'+esc(t.source)+'" target="_blank" rel="noopener">传统规则参考 ↗</a>':'')+'</div></article>';}).join('')+'</div><div class="detail-links">各档累计奖励请悬浮对应羁绊查看；只取达到的最高档。原麻将和牌条件与本游戏判定不同。<br><a href="synergies.md" target="_blank" rel="noopener">日麻／国标／川麻／台麻牌型整理 ↗</a></div>');}
function pools(){const p=game.players[0],rate=game.config.odds[p.level];return modal('<h2 class="modal-title">牌山与牌源</h2><p class="modal-sub">实体有限 · 每次摸牌随机抽取，没有固定牌序。</p><div class="pool-stats"><div><small>公共牌山</small><strong>'+game.public.length+'</strong><span>剩余可抽实体</span></div><div><small>你的个人池</small><strong>'+p.pool.length+'</strong><span>'+(p.packs.join(' / ')||'第2、5次比拼后做局')+'</span></div></div><div class="rules-content"><p>完成首次做局后，商店默认2张个人池＋3张公共池。个人池不受本数限制；来源不足时使用另一来源补位。</p><p>当前商店每个空维度追加率 '+number(rate*100)+'%。个人包已有颜色、纹路、材质会保留，已为三重的牌跳过；已有牌不会被覆盖。</p><p>升本下一回合生效，手牌容量每本＋3。</p></div>',{small:true});}
function render(){hideTooltip();if(game.phase==='showdown'&&!game.preparation)game.beginShowdown({paced:true});if(ui.round!==game.round){ui.round=game.round;ui.shopHidden=false;}const r=playerScore();$('#app').innerHTML='<main class="table-scene '+(ui.push?'table-pushing':'')+'" aria-label="四人麻将牌桌">'+board()+'<div class="table-hud"><button class="table-brand" data-action="help"><span>雀</span><b>雀序</b></button><div class="table-toolbar"><button id="account-launcher" type="button" aria-label="本地账号与存档"></button><button data-action="catalog" title="羁绊图鉴" aria-label="羁绊图鉴">◈</button><button data-action="logs" title="对局记录" aria-label="对局记录">☷</button><button data-action="sound" title="'+(ui.muted?'开启':'关闭')+'音效" aria-label="'+(ui.muted?'开启':'关闭')+'音效">'+(ui.muted?'♪':'♫')+'</button><button data-action="settings" title="新对局与存档" aria-label="新对局与存档">⚙</button></div></div>'+preparationBanner()+synergyPanel(r)+hand()+market()+'</main>';renderModal();save();accountUI?.attach();scheduleDiscards();schedulePreparation();}
function modal(content,{small=false,close=true}={}){return `<div class="modal-backdrop"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-label="${esc(content.match(/<h2[^>]*>(.*?)<\/h2>/)?.[1]||'牌局窗口')}">${close?'<button class="close-btn" data-action="close" aria-label="关闭">×</button>':''}${content}</section></div>`;}
function preparationBanner(){const p=game.preparation;if(!p&&!ui.push)return '';const selecting=p?.stage==='select',status=ui.push?'四家推牌 · 即将展示':p.stage==='intro'?'下家先行 · 依次取牌、出牌':selecting?'轮到你 · 点击自己的牌河取牌，点击手牌选择打出':game.pending?'鸣牌响应中 · 出牌顺序暂时暂停':p.stage==='ready'?'四家配牌完成':game.players[game.turn].name+'正在'+(game.presentation?.kind==='prepare'?'取牌':'出牌');return '<section class="preparation-banner" role="status" aria-live="polite"><strong>'+(ui.push?'推牌！':'对决开始！')+'</strong><p>从牌河中挑选你的手牌，再把多余牌打出。</p><div class="preparation-order">'+[1,2,3,0].map(i=>'<span class="'+(p?.completed.includes(i)?'done':i===game.turn?'current':'')+'">'+game.players[i].name+'</span>').join('<i>→</i>')+'</div><small>'+status+'</small></section>';}
let preparationJob=null;
function schedulePreparation(){const p=game.preparation;if(!p||ui.push||ui.scoring||ui.modal||preparationJob?.game===game&&preparationJob.stage===p.stage)return;if(p.stage==='intro'){const job={game,stage:p.stage};preparationJob=job;setTimeout(()=>{if(preparationJob===job)preparationJob=null;if(game!==job.game||game.preparation?.stage!=='intro'||ui.modal)return;game.startPreparation();render();},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1300);}else if(p.stage==='ready'){const job={game,stage:p.stage};preparationJob=job;queueMicrotask(()=>{if(preparationJob===job)preparationJob=null;if(game!==job.game||game.preparation?.stage!=='ready')return;game.settle();ui.discard.clear();const push={game,report:game.reports.at(-1)};ui.push=push;render();setTimeout(()=>{if(ui.push!==push||game!==push.game)return;ui.push=null;startScoring();render();},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1000);});}}
async function playPreparation(job){try{if(!matchMedia('(prefers-reduced-motion: reduce)').matches)await new Promise(resolve=>setTimeout(resolve,900));}finally{if(flightJob===job)flightJob=null;if(game===job.game&&game.presentation?.kind==='prepare'&&game.presentation.i===job.i){game.advancePreparation();render();}}}
function resultFormula(r){if(!r.trace)return '历史规则 · 基础 '+number(r.base)+' × (1＋'+r.fan+'番 × '+game.config.fanRate+') ＋ 宝牌 '+r.dora+' − 捉鸡 '+r.penalty;return '加法 '+number(r.base)+'＋宝牌 '+number(r.dora)+'＋水晶 '+number(r.crystalSymbols||0)+'＝'+number(r.symbols)+'符 → 主番 ×'+number(r.fanMultiplier)+r.extras.map(e=>' → '+esc(e.label)+' ×'+number(e.factor)).join('')+' → '+number(r.gain)+'分';}
function results(report=game.reports.at(-1),historic=false){if(!report)return modal('<h2 class="modal-title">尚无对决记录</h2><p class="modal-sub">第3回合结束后进行首次对决。</p>');const over=game.phase==='over'&&!historic,ranking=game.players.map((p,i)=>({...p,i})).sort((a,b)=>b.score-a.score),winner=ranking.filter(p=>p.score===ranking[0].score).map(p=>p.name).join('、');return modal(`<h2 class="modal-title">${over?'八局已毕 · 胜负揭晓':'第'+report.round/3+'次对决 · 结算'}</h2><p class="modal-sub">展示分与回手成长分别结算。黄金、玉的回收收益需承担被他家鸣走的风险。</p>${over?`<div class="rank-banner">${winner.includes('你')?'你赢得了这场牌局。':winner+'赢得了本局。'}<small>你的累计积分 ${number(game.players[0].score)} · ${ranking.findIndex(p=>p.i===0)+1} / 4 名${ranking.filter(p=>p.score===ranking[0].score).length>1?' · 同分并列获胜':''}</small></div>`:''}<div class="result-list">${report.results.map((r,i)=>`<div class="result-row ${i===0?'you':''}"><div class="result-name">${r.name}<small>累计 ${number(r.cumulative)}</small></div><div class="result-tiles">${showcaseMarkup(r,'result')}</div><div class="result-gain">＋${number(r.gain)}<small>本次积分</small></div><div class="result-formula">${resultFormula(r)}${wildSummary(r)?' · 赖子 '+wildSummary(r):''}<br>${r.traits.filter(t=>t.stage).map(t=>`${t.name} ${t.count}张 / ＋${t.fan}番`).join(' · ')||'本轮暂无常规羁绊'}</div></div>`).join('')}</div><div class="modal-actions">${historic?'<button class="secondary" data-action="close">返回牌局</button>':over?'<button class="secondary" data-action="logs">查看记录</button><button class="primary" data-action="settings">再开一局 →</button>':`<button class="primary" data-action="continue">${[6,15].includes(game.round)?'进入做局 · 三选一':'进入下一回合'} →</button>`}</div>`,{close:historic});}
function draft(){return modal(`<h2 class="modal-title">做局 · 选择你的牌源</h2><p class="modal-sub">${game.players[0].packs.length?'第二次':'第一次'}扩池。选一套36张牌加入个人池，不受本数限制。包内已有异色与商店概率叠加，已有维度保留，三重牌跳过追加。</p><div class="draft-grid">${game.drafts.map((p,i)=>{const total=p.tiles.length,any=p.tiles.filter(t=>dimensions(t)>0).length,multi=p.tiles.filter(t=>dimensions(t)>=2).length;return `<button class="draft-card" data-action="pack" data-index="${i}"><span class="pack-symbol">${p.name[0]}</span><h3>${p.name}</h3><p>${p.name==='幺九'?'六种一九，各6张':p.name==='全中'?'三种五，各12张':p.name==='字一色'?'四风各6张，三元各4张':'一至九，每种4张'} · 共${total}张</p>${[['color','颜色'],['pattern','纹路'],['material','材质']].map(([key,label])=>`<div class="draft-stat"><span>${label}异色</span><b>${p.counts[key]}张 · ${number(p.counts[key]/total*100)}%</b></div>`).join('')}<div class="draft-stat"><span>特殊覆盖／多维</span><b>${any} / ${multi}张</b></div><div class="draft-sample">${p.tiles.filter(t=>dimensions(t)>0).slice(0,4).map(t=>face(t,'mini')).join('')}</div><div class="draft-pick">选择此牌池 ＋ →</div></button>`;}).join('')}</div><div class="intro-strip">后续商店正常为2张个人＋3张公共；公共池不足时由本人个人池补位。每张牌同一羁绊只计一次。</div>`,{close:false});}
function findTile(uid){for(const p of game.players){const t=[...owned(p),...p.river,...p.shop.filter(Boolean),...p.pool].find(t=>t.uid===uid);if(t)return t;}return game.public.find(t=>t.uid===uid)||game.destroyed.find(t=>t.uid===uid);}
function details(uid){const t=findTile(uid);if(!t)return modal('<h2 class="modal-title">牌已离开当前区域</h2>',{small:true});return modal(`<h2 class="modal-title">${info(t).name} · 牌详情</h2><div class="detail-layout">${face(t,'large')}<div class="detail-data">颜色：<b>${COLORS[t.color]||'常规'}</b><br>纹路：<b>${t.pattern?info(t.pattern).name+'（仅羁绊）':'无'}</b><br>材质：<b>${MATERIALS[t.material]||'普通'}</b><br>成长倍率：<b>×${number((t.material==='jade'?jadeMultiplier(t):1)*(t.diamond||1))}</b><br>牌级价格：<b>买入 ${buyPrice(t)}G / 售出 ${sellPrice(t)}G</b><br>异色维度：<b>${dimensions(t)} / 3</b><br>来源：<b>${t.origin==='public'?'公共牌池':'个人做局池'}</b>${t.jadePending?'<br><span class="text-gold">玉牌待对决后倍率＋0.5</span>':''}</div></div><p class="modal-sub">${t.material==='gold'?'弃入牌河赚'+game.config.goldYield+'G；被他家鸣走后失去未来回收权。':t.material==='jade'?'初始倍率×1.5；弃入牌河，对决配牌取回并保留至展示结束时倍率＋0.5；新增成长从下一次对决生效。':t.material==='crystal'?'展示＋10符、＋5主番，在玉和钻石倍率之前结算；弃入牌河先碎裂，不开放鸣牌。':t.material==='diamond'?'被他家鸣走的此牌翻倍；实际展示后重置。':'纹路不改变吃碰杠身份；同一实体在同一羁绊只贡献一次。'}</p>${game.phase==='shop'&&game.players[0].hand.some(x=>x.uid===t.uid)?`<div class="modal-actions"><button class="secondary" data-action="sell" data-uid="${t.uid}">卖出此牌 · ＋${sellPrice(t)}G</button></div>`:''}`,{small:true});}
function help(){return modal(`<h2 class="modal-title">牌局手册 · v0.13.0</h2><p class="modal-sub">四人麻将自走棋 · 24回合 · 八次对决 · 本地账号</p><div class="rules-content"><h3>买牌与牌桌</h3><p>初始5G，每回合四家各摸5张，最多购买3张，首张免费。商店可花2G退回未购买的牌并重抽5张，次数不限，但不重置本回合购买次数或首张免费状态；已买满3张后不可换牌。一本至四本买入2／3／4／5G、卖出1／2／3／4G，对应白／蓝／紫／橙底板；异色另叠加渐变与花纹。升本费用6／10／14G，每次容量＋3，容量为5／8／11／14。每回合收入${game.config.income}G。拖动手牌或Alt＋方向键可调整顺序。</p><h3>逐张出牌、鸣牌与配牌</h3><p>所有人买完后轮流出牌，每张落地后可鸣。杠优先于碰，碰优先于吃，同级按座次；只允许下家吃。鸣牌按钮在手牌右上方。副露锁定至下次对决，杠使容量−1，展示后副露回手。</p><p>每3回合在原牌桌配牌：从你的下家起，依次从自己的牌河取牌并打出多余手牌，每张弃牌仍可被鸣。最后轮到你，完成后四家推牌，其他家快速计分，你的牌最后逐组跳分。</p><h3>异色与做局</h3><p>公共池147张，牌山随机无序。商店每维追加异色率随本数为1.6%／3%／4.6%／6.4%，已降至原版本整牌异色概率的三分之一以内。个人牌先保留已有维度，再对空维度追加商店判定；三重牌跳过。纹路覆盖整张牌、每2秒扫光，仅提供羁绊身份，不参与吃碰杠，同一羁绊不重复计数。</p><p>第2、5次对决后各扩充一次个人池。每包36张，个人池不受本数限制，商店按个人2张＋公共3张抽取；来源不足时用另一来源补位。</p><h3>羁绊</h3><p>17种常规羁绊采用各自的组件门槛，完整档位见图鉴和悬浮说明。各档默认累计＋1／2／3／4／5／6／7主番，只取已达到的最高档。纯全幺6／8／9／11／12／14档依次为两搭、两搭带雀头、三搭、三搭带雀头、四搭、四搭带雀头，搭子限定123／789／111／999，雀头限定11／99，最多一个。</p><p>至少3张真实红中激活赖子：从左往右复制左邻已解析牌面，保留自己的异色和成长；最左红中无左邻时不变。拖动可改变复制目标。捉鸡与宝牌按结算牌面判断，鸣牌仍按本体。</p><p>一索／八筒合计至少2张激活捉鸡：本家相关牌的基础符×2；每名其他发动者使你展示的每张相关牌在最后乘×${number(1-game.config.chickenPenalty)}。两张红宝激活宝牌，指示物下一张各加3符，场上每杠使已激活者多翻一个指示物。</p><h3>材质与计分顺序</h3><p>黄金实际弃出赚${game.config.goldYield}G；玉初始×1.5，弃入牌河并取回、保留至对决结束后倍率＋0.5，从以后对决兑现；钻石被鸣时自身成长×2，展示后重置；水晶展示＋10符、＋${game.config.crystalFan}主番，在玉与钻石前结算；打出即碎。</p><p>常规最多四搭（刻子、顺子或整副杠）及一个雀头计基础符；小七对6组件激活后，全部原牌面对子另行计符，可重复使用四搭和雀头中的牌；国士9组件后所有结算牌面的幺九字可计符。常规轮次内不复用，小七对轮次可再次计符。散牌仍可提供羁绊、颜色番、宝牌和材质效果。</p><p>展示自动按有效牌组码牌，仅改变展示排列，不改变赖子左邻。先算四搭加一个雀头，再独立计全部小七对子与补计国士散张符数、宝牌符数；然后逐项弹出已激活羁绊，每项加番后按累计番数立即重算当前分数，19番直接×19，无番按×1，然后逐张计算水晶＋10符及＋${game.config.crystalFan}番，再按手牌顺序依次乘玉牌成长、钻石成长，最后乘捉鸡压制。中途不取整，只对最终分四舍五入。八次对决累计最高者获胜。</p><h3>本地账号</h3><p>每位本机玩家独立保存牌局，可切换、改名、备份和导入。旧账号和历史成绩保留，升级后未来对决采用新规则。清除浏览器数据会删除本地进度，换设备可导入账号备份。</p><p><a href="rules.md" target="_blank" rel="noopener">规则与计分参数 ↗</a> · <a href="synergies.md" target="_blank" rel="noopener">羁绊档位表 ↗</a></p></div>`);}

// Presentation reads the immutable report. Scores are settled exactly once in Game.
let scoreAudio;
function scoreTone(step,final=false){if(ui.muted)return;try{scoreAudio??=new(window.AudioContext||window.webkitAudioContext)();scoreAudio.resume();const ctx=scoreAudio,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=final?'triangle':'sine';osc.frequency.setValueAtTime(220+Math.min(step,12)*45,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(final?880:140,ctx.currentTime+.16);gain.gain.setValueAtTime(final?.075:.045,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.23);}catch{}}
function scoringScreen(){const s=ui.scoring;return `<div class="modal-backdrop scoring-backdrop"><section class="scoring-modal" role="dialog" aria-modal="true" aria-label="对决逐组计分"><div class="scoring-top"><span>第 ${s.report.round/3} 次对决</span><button data-action="score-skip">跳过动画 →</button></div><div class="scoring-order">${[1,2,3,0].map(i=>`<div data-score-seat="${i}" class="${i===s.seat?'current':''}"><span>${s.report.results[i].name}</span><b>${s.finished.has(i)?'＋'+number(s.report.results[i].gain):i===s.seat?'展示中':'待展示'}</b></div>`).join('')}</div><div id="score-stage"></div><div class="score-footer"><span id="score-announcement" role="status" aria-live="polite">其他三家快速展示，最后结算你的牌。</span><button data-action="score-sound">${ui.muted?'开启计分音效 ♪':'关闭计分音效 ♫'}</button></div></section></div>`;}
function scoreStage(i){const r=ui.scoring.report.results[i],valid=new Set(r.groups.flatMap(g=>g.uids));return `<div style="--score-tempo:${i===0?1/1.5:2}" class="score-focus ${i===0?'player-focus':''}"><div class="score-kicker">${i===0?'轮到你了 · 逐组计分':'对手展示 · 快速结算'}</div><h2>${r.name}<small>${r.scoredCount} / ${r.tiles.length} 张计基础符</small></h2><div class="score-show-tiles">${showcaseMarkup(r)}</div><div class="score-instrument"><div class="score-base-block"><small>加法区 · 符数</small><b id="score-base">0</b></div><span class="score-times">×</span><div class="score-mult-block"><small id="score-fan-label">0 番 · 无番按×1</small><b id="score-mult">1</b></div><span class="score-times">×</span><div class="score-extra-block"><small>特殊倍率</small><b id="score-extra">1</b></div><span class="score-equals">=</span><div class="score-total-block"><small id="score-total-label">准备计分</small><b id="score-total">0</b></div></div><div id="score-callout" class="score-callout" aria-live="polite"></div><div id="score-event" class="score-event">${r.groups.length?'准备揭示有效牌组':'没有有效牌组 · 基础符为0'}</div><div class="score-detail">${wildSummary(r)?'赖子复制 '+wildSummary(r)+' · ':''}颜色 ＋${r.colorFan}主番 · 羁绊 ＋${r.traitFan}主番<br>宝牌 ＋${r.dora}符 · 水晶 ＋${r.crystalSymbols||0}符／＋${r.materialFan}番，先于玉与钻石</div><div class="score-particles" aria-hidden="true"></div></div>`;}

function startScoring(){ui.scoring={report:game.reports.at(-1),seat:1,finished:new Set()};const active=ui.scoring;setTimeout(()=>playScoring(active),30);}
function pulseScore(el,strong=false){if(!el)return;el.classList.remove('score-punch','score-punch-strong');void el.offsetWidth;el.classList.add(strong?'score-punch-strong':'score-punch');}
function scoreBurst(uids,label,strong){const stage=$('#score-stage'),focus=stage?.querySelector('.score-focus'),layer=stage?.querySelector('.score-particles');if(!focus||!layer)return;const tempo=Number(focus.style.getPropertyValue('--score-tempo'))||1,r=focus.getBoundingClientRect();let x=r.width/2,y=r.height*.44;
 const hits=uids.map(uid=>stage.querySelector('[data-score-uid="'+uid+'"]')).filter(Boolean);if(hits.length){const bounds=hits.map(el=>el.getBoundingClientRect());x=bounds.reduce((v,b)=>v+b.left+b.width/2-r.left,0)/bounds.length;y=bounds.reduce((v,b)=>v+b.top-r.top,0)/bounds.length;for(const el of hits){el.classList.remove('is-hit');void el.offsetWidth;el.classList.add('is-hit');}}
 const popup=document.createElement('span');popup.className='score-popup';popup.textContent=label;popup.style.left=x+'px';popup.style.top=y+'px';layer.appendChild(popup);setTimeout(()=>popup.remove(),1000*tempo);
 for(let j=0;j<(strong?28:9);j++){const p=document.createElement('i'),angle=j*2.39996,distance=(strong?70:30)+(j%5)*15;p.style.cssText=`left:${x}px;top:${y+30}px;--dx:${Math.cos(angle)*distance}px;--dy:${Math.sin(angle)*distance-45}px;--spin:${j*77}deg;--particle:${['#fff3b3','#e3b45d','#a8e1b7','#ffeddf'][j%4]};animation-delay:${j%3*12}ms`;layer.appendChild(p);setTimeout(()=>p.remove(),1100*tempo);}
 if(strong){pulseScore(focus,true);const ring=document.createElement('em');ring.style.left=x+'px';ring.style.top=y+30+'px';layer.appendChild(ring);setTimeout(()=>ring.remove(),700*tempo);}
}
async function playScoring(active){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,wait=ms=>new Promise(resolve=>setTimeout(resolve,reduced?0:ms)),alive=()=>ui.scoring===active&&!!$('#score-stage');
 try{for(const i of [1,2,3,0]){
  if(!alive())return;const r=active.report.results[i],human=i===0,tempo=human?1/1.5:2;active.seat=i;
  for(const el of document.querySelectorAll('[data-score-seat]')){el.classList.toggle('current',Number(el.dataset.scoreSeat)===i);if(Number(el.dataset.scoreSeat)===i)el.querySelector('b').textContent='展示中';}
  delete $('#score-stage').dataset.area;delete $('#score-stage').dataset.presentation;delete $('#score-stage').dataset.stepLabel;$('#score-stage').innerHTML=scoreStage(i);$('#score-announcement').textContent=human?'基础算符 → 牌型名称 → 对应牌 → 特殊牌加番／倍率':'对手依次展示 · '+r.name;await wait((human?520:90)*tempo);let hit=0,extraMultiplier=1;
  for(const step of r.trace.steps){
   if(!alive())return;const additive=step.area==='add',trait=step.area==='trait',bonus=step.area==='special-fan',symbolBonus=step.area==='special-symbols',label=additive||symbolBonus?'＋'+number(step.amount)+' 符':trait||bonus?'＋'+number(step.fan)+' 番':'×'+number(step.factor),stage=$('#score-stage'),callout=$('#score-callout'),uids=step.uids||[step.uid].filter(Boolean);
   stage.dataset.area=step.area;stage.dataset.stepLabel=step.label;stage.dataset.presentation='name';
   for(const tile of stage.querySelectorAll('.score-tile'))tile.classList.remove('is-component','is-hit');
   callout.className='score-callout '+(!additive?'is-visible':'');callout.innerHTML=!additive?'<small>'+(trait?'牌型发动 · '+step.count+'组件 · 第'+step.stage+'档':symbolBonus?'特殊牌 · 加符':bonus?'特殊牌 · 加番':'特殊乘区')+'</small><strong>'+esc(step.label)+'</strong><b>'+label+'</b>':'';
   if(!additive){void callout.offsetWidth;callout.classList.add('callout-pop');$('#score-event').textContent=step.label+' · '+(trait?'接下来展示参与牌':label);await wait(human?300:110);if(!alive())return;}
   stage.dataset.presentation='cards';for(const uid of uids)stage.querySelector('[data-score-uid="'+uid+'"]')?.classList.add('is-component');
   if(!reduced){scoreBurst(uids,label,human);scoreTone(++hit);}
   // A short held impact precedes this step's immediate score update.
   if(!additive){await wait(human?300:110);if(!alive())return;}
   if(additive){$('#score-base').textContent=number(step.after);$('#score-total-label').textContent='基础符 · '+step.label;}
   else if(symbolBonus){$('#score-base').textContent=number(step.symbols);$('#score-total-label').textContent='加符已计入 · '+step.label;}else if(trait||bonus){$('#score-fan-label').textContent=(step.accumulatedFan||0)+' 番 · 直接倍率';$('#score-mult').textContent=number(step.mainMultiplier);$('#score-mult').dataset.multiplier=String(step.mainMultiplier);$('#score-total-label').textContent='加番已计入 · '+step.label;}
   else{extraMultiplier*=step.factor;$('#score-extra').textContent=number(extraMultiplier);$('#score-extra').dataset.multiplier=String(extraMultiplier);$('#score-total-label').textContent='乘倍已计入 · '+step.label;}
   $('#score-total').textContent=number(step.after);$('#score-total').dataset.unroundedValue=String(step.after);$('#score-event').textContent=step.label+' '+label+' → 当前 '+number(step.after)+' 分';stage.dataset.presentation='applied';
   if(!reduced){pulseScore($('#score-total'),human);pulseScore(additive||symbolBonus?$('#score-base'):trait||bonus?$('#score-mult'):$('#score-extra'),human);}
   await wait(additive?(human?560:55)*tempo:human?160:110);
  }
  if(!alive())return;$('#score-callout').className='score-callout';$('#score-stage').dataset.area='final';$('#score-total-label').textContent='最终四舍五入 · 本次得分';$('#score-total').textContent=number(r.gain);$('#score-total').dataset.finalScore=String(r.gain);$('#score-event').textContent='本次入账 ＋'+number(r.gain)+' 分';
  if(!reduced){scoreBurst([],'＋'+number(r.gain)+' 分',human);pulseScore($('#score-total'),human);scoreTone(hit+4,true);}active.finished.add(i);document.querySelector('[data-score-seat="'+i+'"] b').textContent='＋'+number(r.gain);await wait((human?650:100)*tempo);
 }
 if(!alive())return;active.done=true;$('#score-announcement').textContent='计分完成 · 每项效果均已即时计入';const button=document.querySelector('[data-action="score-skip"]');button.dataset.action='score-done';button.textContent='查看本轮结算 →';button.classList.add('score-done');
 }catch{if(ui.scoring===active){ui.scoring=null;renderModal();toast('得分已保存，已显示本轮结算。');}}
}

function renderModal(){if(ui.push){$('#modal-root').innerHTML='';return;}if(ui.scoring){$('#modal-root').innerHTML=scoringScreen();return;}let html='';if(ui.modal){const m=ui.modal;if(m.type==='detail')html=details(m.uid);if(m.type==='help')html=help();if(m.type==='catalog')html=catalog(m.name);if(m.type==='pools')html=pools();if(m.type==='logs')html=modal(`<h2 class="modal-title">对局记录</h2><p class="modal-sub">最新事件在前 · 当前第${game.round}回合</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px">${game.reports.map((r,i)=>`<button class="secondary" data-action="report" data-index="${i}">第${i+1}次 · ＋${r.results[0].gain}</button>`).join('')}</div>${game.log.map(l=>`<div class="log-line"><small>R${String(l.round).padStart(2,'0')}</small><span>${esc(l.text)}</span></div>`).join('')}`);if(m.type==='report')html=results(game.reports[m.index],true);if(m.type==='opponent'){const p=game.players[m.player];html=modal(`<h2 class="modal-title">${p.name} · 公开牌区</h2><p class="modal-sub">${p.level}本 · 累计${p.score}分 · 只展示公开牌河和副露，普通手牌隐藏。</p><div class="group-label">牌河 · ${p.river.length}张</div><div class="showcase-pool">${p.river.map(t=>face(t)).join('')||'<span class="muted">暂无弃牌</span>'}</div><div class="group-label">明牌副露</div><div class="showcase-pool">${p.melds.flatMap(m=>m.tiles).map(t=>face(t)).join('')||'<span class="muted">暂无副露</span>'}</div>`,{small:true});}if(m.type==='settings')html=modal(`<h2 class="modal-title">新对局 · v0.13.0</h2><p class="modal-sub">重新开始将替换当前自动存档，可先导出保存。下列数值仅供原型调试。</p><div class="settings-grid"><label>每回合收入<input id="cfg-income" type="number" min="0" max="30" value="${game.config.income}"></label><label>牌级买入／售出<span class="price-reference">白 2/1 · 蓝 3/2 · 紫 4/3 · 橙 5/4 G</span></label><label>黄金弃出收益<input id="cfg-gold" type="number" min="0" max="20" value="${game.config.goldYield}"></label><label>主番计分<span class="price-reference">19番＝×19 · 无番按×1</span></label><label>随机种子<input id="cfg-seed" type="number" value="${Date.now()%100000000}"></label><label>导入存档<input id="import-save" type="file" accept=".json,application/json"></label></div><div class="modal-actions"><button class="secondary" data-action="export">导出当前存档</button><button class="primary" data-action="newgame">开始新牌局 →</button></div>`,{small:true});}
 else if(game.phase==='result'||game.phase==='over')html=results();else if(game.phase==='draft')html=draft();
 $('#modal-root').innerHTML=html;
}
// Each queue pause is an owned tile awaiting its landing, not an extra entity.
let flightJob=null,handDrag=null,dragClickUntil=0;
function canReorder(){return !ui.push&&(['shop','trim'].includes(game.phase)||game.phase==='showdown'&&game.preparation?.stage==='select'||game.pending?.options[0]?.to===0);}
function landingSound(){if(ui.muted)return;try{scoreAudio??=new(window.AudioContext||window.webkitAudioContext)();const ctx=scoreAudio;ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(170,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(62,ctx.currentTime+.12);g.gain.setValueAtTime(.12,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.15);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.16);const buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.055),ctx.sampleRate),samples=buffer.getChannelData(0);for(let j=0;j<samples.length;j++)samples[j]=(Math.random()*2-1)*Math.exp(-j/(ctx.sampleRate*.009));const click=ctx.createBufferSource(),cg=ctx.createGain(),filter=ctx.createBiquadFilter();click.buffer=buffer;filter.type='highpass';filter.frequency.value=1500;cg.gain.value=.15;click.connect(filter);filter.connect(cg);cg.connect(ctx.destination);click.start();}catch{}}
function scheduleDiscards(){if(game.presentation){const p=game.presentation;if(flightJob?.game===game&&flightJob.uid===p.uid&&flightJob.i===p.i&&flightJob.kind===p.kind)return;const job={game,uid:p.uid,i:p.i,kind:p.kind};flightJob=job;requestAnimationFrame(()=>p.kind==='prepare'?playPreparation(job):playDiscard(job));}else if(game.phase==='resolving'&&!game.pending&&game.queue.length){queueMicrotask(()=>{if(game.phase==='resolving'&&!game.presentation&&!game.pending){game.run();render();}});}}
async function playDiscard(job){let flying;const alive=()=>game===job.game&&game.presentation?.uid===job.uid;try{
 if(!alive())return;const t=game.players[job.i].hand.find(t=>t.uid===job.uid),target=$('[data-landing-uid="'+job.uid+'"]');if(!t||!target)throw Error('落点未显示');target.scrollIntoView({block:'nearest',inline:'nearest'});const dest=target.getBoundingClientRect(),source=job.i===0?$('.hand-tiles [data-action="handtile"][data-uid="'+job.uid+'"]'):$('.edge-'+job.i+' .hidden-tiles'),src=source?.getBoundingClientRect()||dest,angle=[0,-90,180,90][job.i],w=target.querySelector('.tile-face').offsetWidth,h=target.querySelector('.tile-face').offsetHeight;
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches){flying=document.createElement('div');flying.className='discard-flight';flying.setAttribute('aria-hidden','true');flying.innerHTML=face(t);flying.style.cssText=`left:${dest.left+dest.width/2}px;top:${dest.top+dest.height/2}px;width:${w}px;height:${h}px;--land-angle:${angle}deg`;document.body.appendChild(flying);source?.classList.add('discard-source');const dx=src.left+src.width/2-dest.left-dest.width/2,dy=src.top+src.height/2-dest.top-dest.height/2;
  await flying.animate([{transform:`translate(-50%,-50%) translate(${dx}px,${dy}px) rotate(${angle-8}deg) scale(1.8)`,offset:0},{transform:`translate(-50%,-50%) translate(${dx*.42}px,${dy*.42-35}px) rotate(${angle+8}deg) scale(1.5)`,offset:.46},{transform:`translate(-50%,-50%) rotate(${angle}deg) scale(1.1)`,offset:.82},{transform:`translate(-50%,-50%) rotate(${angle}deg) scale(.93)`,offset:.9},{transform:`translate(-50%,-50%) rotate(${angle}deg) scale(1)`,offset:1}],{duration:580,easing:'cubic-bezier(.2,.65,.38,1)',fill:'forwards'}).finished;
  if(!alive())return;landingSound();flying.classList.add('landed');await new Promise(resolve=>setTimeout(resolve,220));
 }else landingSound();
 }catch{if(alive())landingSound();}finally{flying?.remove();document.querySelectorAll('.discard-source').forEach(el=>el.classList.remove('discard-source'));if(flightJob===job)flightJob=null;if(alive()){const uid=job.uid;game.advanceDiscard();render();const landed=$('[data-river-uid="'+uid+'"]');if(landed){landed.classList.add('river-landed');setTimeout(()=>landed.classList.remove('river-landed'),650);}}}}

function cleanHandDrag(commit=false){const d=handDrag;if(!d)return;handDrag=null;d.ghost?.remove();d.button.classList.remove('hand-drag-source');try{d.button.releasePointerCapture(d.pointer);}catch{}if(d.moved){dragClickUntil=performance.now()+400;if(commit&&canReorder()){const order=[...document.querySelectorAll('.hand-tiles > .tile-wrap > .tile-button')].map(el=>Number(el.dataset.uid)),at=order.indexOf(d.uid);if(at>=0)game.reorderHand(d.uid,order[at+1]??null);}render();}}
document.addEventListener('pointerdown',e=>{const button=e.target.closest('.hand-tiles > .tile-wrap > .tile-button');if(!button||button.disabled||e.button!==0||!canReorder()||ui.modal||ui.scoring)return;handDrag={uid:Number(button.dataset.uid),pointer:e.pointerId,x:e.clientX,y:e.clientY,button,wrap:button.closest('.tile-wrap'),moved:false};button.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{const d=handDrag;if(!d||d.pointer!==e.pointerId)return;if(!d.moved&&Math.hypot(e.clientX-d.x,e.clientY-d.y)<8)return;e.preventDefault();hideTooltip();if(!d.moved){d.moved=true;d.button.classList.add('hand-drag-source');d.ghost=document.createElement('div');d.ghost.className='hand-drag-ghost';d.ghost.setAttribute('aria-hidden','true');d.ghost.appendChild(d.button.querySelector('.tile-face').cloneNode(true));const b=d.button.getBoundingClientRect();d.ghost.style.width=b.width+'px';d.ghost.style.height=b.height+'px';document.body.appendChild(d.ghost);}d.ghost.style.left=e.clientX+'px';d.ghost.style.top=e.clientY+'px';const row=$('.hand-tiles'),bounds=row.getBoundingClientRect();if(e.clientX<bounds.left+30)row.scrollLeft-=12;if(e.clientX>bounds.right-30)row.scrollLeft+=12;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.hand-tiles > .tile-wrap');if(target&&target!==d.wrap){const b=target.getBoundingClientRect();row.insertBefore(d.wrap,e.clientX<b.left+b.width/2?target:target.nextElementSibling);}else if(e.clientY>=bounds.top&&e.clientY<=bounds.bottom&&e.clientX>bounds.right-20)row.insertBefore(d.wrap,row.querySelector('.melds'));},{passive:false});
document.addEventListener('pointerup',e=>{if(!handDrag||handDrag.pointer!==e.pointerId)return;const row=$('.hand-tiles').getBoundingClientRect(),inside=e.clientY>=row.top-30&&e.clientY<=row.bottom+20&&e.clientX>=row.left-15&&e.clientX<=row.right+15;cleanHandDrag(inside);});
document.addEventListener('pointercancel',()=>cleanHandDrag());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&handDrag?.moved){e.preventDefault();e.stopImmediatePropagation();cleanHandDrag();return;}const button=e.target.closest?.('.hand-tiles > .tile-wrap > .tile-button');if(!button||!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key)||!canReorder())return;e.preventDefault();const p=game.players[0],uid=Number(button.dataset.uid),i=p.hand.findIndex(t=>t.uid===uid);if(e.key==='ArrowLeft'&&i>0)game.reorderHand(uid,p.hand[i-1].uid);if(e.key==='ArrowRight'&&i<p.hand.length-1)game.reorderHand(uid,p.hand[i+2]?.uid??null);render();$('.hand-tiles [data-uid="'+uid+'"]')?.focus();},true);
window.addEventListener('resize',()=>cleanHandDrag());

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(action==='handtile'&&performance.now()<dragClickUntil)return;if(game.presentation&&action!=='sound')return;if(ui.push&&action!=='sound')return;if(ui.scoring&&!['score-skip','score-done','score-sound'].includes(action))return;try{if(action==='score-skip'||action==='score-done'){ui.scoring=null;hideTooltip();renderModal();return;}else if(action==='score-sound'){ui.muted=!ui.muted;el.textContent=ui.muted?'开启计分音效 ♪':'关闭计分音效 ♫';scoreTone(4);return;}else if(action==='sell'){const uid=Number(el.dataset.uid),earned=game.sell(uid);ui.discard.delete(uid);ui.modal=null;toast('卖出获得'+earned+'G');sound();}else if(action==='shop-toggle'){ui.shopHidden=!ui.shopHidden;}else if(action==='traits'){ui.traitsExpanded=!ui.traitsExpanded;}else if(action==='catalog'){ui.modal={type:'catalog'};}else if(action==='trait'){ui.modal={type:'catalog',name:el.dataset.name};}else if(action==='pools'){ui.modal={type:'pools'};}else if(action==='buy'){const t=game.buy(0,Number(el.dataset.index));toast(`购入${describe(t)}`);sound();}else if(action==='refresh-shop'){game.refreshShop();toast('花费2G换牌 · 本回合已购'+game.players[0].buys+'/3');sound();}else if(action==='upgrade'){game.upgrade();toast(`已升至${game.players[0].level}本，新增异色率从下次换牌或下回合生效`);sound();}else if(action==='handtile'){if(!['shop','trim'].includes(game.phase)&&!(game.phase==='showdown'&&game.preparation?.stage==='select'))return;const uid=Number(el.dataset.uid);ui.discard.has(uid)?ui.discard.delete(uid):ui.discard.add(uid);}else if(action==='sort'){game.players[0].hand.sort((a,b)=>TYPES.findIndex(t=>t.id===a.face)-TYPES.findIndex(t=>t.id===b.face));}else if(action==='main'){ui.modal=null;if(game.phase==='shop'){game.finishHuman([...ui.discard],{paced:true});ui.discard.clear();}else if(game.phase==='trim'){game.finishClaimTrim([...ui.discard]);ui.discard.clear();}else if(game.phase==='showdown'){game.finishPreparation([...ui.discard]);ui.discard.clear();}}else if(action==='take-river'){const t=game.takeRiver(Number(el.dataset.uid));toast('取回'+info(t).name);sound();}else if(action==='continue'){game.continue();}else if(action==='pack'){game.choosePack(Number(el.dataset.index));sound();}else if(action==='claim'){game.claim(Number(el.dataset.index));ui.discard.clear();}else if(action==='close'){ui.modal=null;}else if(action==='detail'){ui.modal={type:'detail',uid:Number(el.dataset.uid)};}else if(action==='opponent'){ui.modal={type:'opponent',player:Number(el.dataset.player)};}else if(action==='help'||action==='logs'||action==='settings'){ui.modal={type:action};}else if(action==='report'){ui.modal={type:'report',index:Number(el.dataset.index)};}else if(action==='sound'){ui.muted=!ui.muted;sound();toast(ui.muted?'音效已关闭':'音效已开启');}else if(action==='export'){const blob=new Blob([game.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`雀序-第${game.round}回合.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出');return;}else if(action==='newgame'){const get=(id,min,max)=>{const n=Number($(id).value);if(!Number.isFinite(n)||n<min||n>max)throw Error('参数超出允许范围');return n;};account.newRun();game=new Game(get('#cfg-seed',0,Number.MAX_SAFE_INTEGER),{income:get('#cfg-income',0,30),goldYield:get('#cfg-gold',0,20)});ui.modal=null;ui.discard.clear();ui.shopHidden=false;ui.traitsExpanded=false;toast('新局已开，首张免费');}render();}catch(err){toast(err.message||'操作未完成');render();}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-save')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw Error('存档过大');const restored=Game.restore(await file.text());account.newRun();game=restored;ui.modal=null;ui.discard.clear();render();toast('存档已恢复');}catch(err){toast(err.message||'存档无效');}});
document.addEventListener('keydown',e=>{if(ui.scoring||ui.push||game.presentation)return;if(e.key==='Escape'){if(!ui.modal&&game.pending?.options[0]?.to===0){game.claim(-1);render();return;}if(ui.modal){ui.modal=null;renderModal();}else if(game.phase==='shop'){ui.shopHidden=!ui.shopHidden;render();}} });

// One floating tooltip works across hands, offers, rivers and modal snapshots.
const TIP_SELECTOR='[data-tooltip-tile],[data-tooltip-trait],[data-tooltip-special]';
let tipAnchor=null,tipFocus=null,tipOpenTimer,tipCloseTimer;
function tileTipAttributes(t){
 if(!dimensions(t))return `title="${esc(info(t).name)}"`;
 const snapshot={face:t.face,color:t.color,pattern:t.pattern,material:t.material,growth:t.growth||1,diamond:t.diamond||1,jadePending:!!t.jadePending,jadeVersion:t.jadeVersion};
 return `data-tooltip-tile="${esc(JSON.stringify(snapshot))}"`;
}
function tipLine(label,effect){return `<div class="tip-effect"><b>${esc(label)}</b><span>${esc(effect)}</span></div>`;}
function tileTip(t){
 let body='';
 if(t.color==='red')body+=tipLine('红宝','自身潜在基础符＋2，主番＋1；两张红宝激活宝牌指示物。基础符需成组才兑现。');
 if(t.color==='green')body+=tipLine('绿牌','自身潜在基础符＋2，主番＋1；为绿一色贡献组件，不替代红宝激活宝牌。');
 if(t.color==='cyan')body+=tipLine('青宝','每张青宝为每张红宝额外＋1主番，多张可叠加。');
 if(t.pattern)body+=tipLine(info(t.pattern).name+'纹路','同时具有'+info(t.face).name+'与'+info(t.pattern).name+'的羁绊身份；同一羁绊一张实体只计一次。吃碰杠只认本体。');
 if(t.material==='gold')body+=tipLine('黄金','实际弃出并落桌时获得'+game.config.goldYield+'G，牌仍可被他家鸣走。卖出不触发。');
 if(t.material==='jade')body+=tipLine('玉','初始×1.5；弃入牌河，取回并保留到对决结束时倍率＋0.5，从下一次起兑现。当前倍率×'+number(jadeMultiplier(t))+'，在符数和主番计算后作为整轮额外倍率。'+(t.jadePending?'本次结束后才能兑现新增成长。':''));
 if(t.material==='crystal')body+=tipLine('水晶','展示＋10符、＋'+game.config.crystalFan+'主番；先加符、再加番并即时重算，在玉和钻石倍率之前触发。多张逐张相加。打出即碎，不能被鸣走。');
 if(t.material==='diamond')body+=tipLine('钻石','此牌被鸣走时成长×2，作为整轮额外倍率，当前×'+number(t.diamond||1)+'；实际展示计分后重置×1。');
 const base=info(t).value+(['red','green'].includes(t.color)?2:0);
 return `<div class="tip-heading"><strong>${info(t.face).name}</strong><small>${['','单重','双重','三重'][dimensions(t)]}异色</small></div>${body}<div class="tip-foot">潜在基础符 ${number(base)}（捉鸡加倍前）。<br>刻子／顺子／整副杠、小七对激活的原牌面对子、国士9档的幺九字兑现基础符。<br>先加符与宝牌，再乘累计主番（19番＝×19，无番按×1），最后逐张乘材质倍率及捉鸡压制。赖子以复制后的结算牌面为准。</div>`;
}

function traitTip(id){
 const t=playerScore().traits.find(t=>t.id===id);if(!t)return '';
 const next=t.thresholds.find(n=>n>t.count);
 const progress=next?`下一档 ${next}张：还需 ${next-t.count} 张有效组件。`:'已达到最高档。';
 return `<div class="tip-heading"><strong>${t.name}</strong><small>${t.count}张组件</small></div><div class="tip-reward">${t.stage?'当前 ＋'+t.fan+'主番':'当前尚未激活'}<b>加入累计主番 · 番数直接作倍率</b></div><div class="tip-tiers">${t.thresholds.map((n,i)=>`<div class="${t.stage===i+1?'current':''}"><span>${n}张</span><b>＋${TRAIT_REWARDS[i+1]}番</b><small>累计番数＋${TRAIT_REWARDS[i+1]}</small></div>`).join('')}</div><p class="tip-progress">${progress}</p><p class="tip-rule">${esc(t.rule)}</p><div class="tip-foot">${id==='pairs'?'6张对子组件激活后，全部原牌面对子独立计符，可再次使用常规轮次的牌。<br>':id==='orphans'?'9档解锁全部结算牌面幺九字的基础符。<br>':''}各档为累计奖励，取达到的最高档；同一实体在同一羁绊只计一次。</div>`;
}

function specialTip(t){
 const active=t.count>=t.need;let effect='';
 if(t.name==='赖子')effect='3张真实红中激活。手牌从左到右，每张红中复制左邻已解析牌面，保留自己的颜色、纹路、材质和成长。最左红中不变，连续红中依次复制，拖动可改变目标。';
 if(t.name==='捉鸡')effect='结算牌面一索／八筒合计至少2张激活，相关牌的基础符×2。每名发动者使其他家每张展示的相关牌在最后乘×'+number(1-game.config.chickenPenalty)+'，即逐次降低'+number(game.config.chickenPenalty*100)+'%。';
 if(t.name==='宝牌')effect='首次持有2张红宝时翻指示物；展示仍需2张红宝，每张结算牌面匹配指示物下一张的牌＋3符，进入加法区后再乘番。场上每杠，已激活者额外翻一张。';
 return `<div class="tip-heading"><strong>${esc(t.name)}</strong><small>${t.count} / ${t.need}张 · ${active?'已激活':'未激活'}</small></div><p class="tip-rule">${effect}</p><div class="tip-foot">${active?'已满足当前组件数量。':'还需 '+(t.need-t.count)+' 张对应组件。'}<br>特殊效果不套用常规羁绊档位。</div>`;
}

function tooltipTarget(node,focus=false){return node instanceof Element?(node.closest(TIP_SELECTOR)||(focus?node.querySelector(TIP_SELECTOR):null)):null;}
function tooltipBox(){let box=$('#hover-tooltip');if(!box){box=document.createElement('div');box.id='hover-tooltip';box.className='hover-tooltip';box.setAttribute('role','tooltip');box.hidden=true;document.body.appendChild(box);box.addEventListener('pointerenter',()=>clearTimeout(tipCloseTimer));box.addEventListener('pointerleave',()=>hideTooltip());}return box;}
function hideTooltip(){clearTimeout(tipOpenTimer);clearTimeout(tipCloseTimer);if(tipFocus?.getAttribute('aria-describedby')==='hover-tooltip')tipFocus.removeAttribute('aria-describedby');tipFocus=null;tipAnchor=null;const box=$('#hover-tooltip');if(box)box.hidden=true;}
function positionTooltip(){const box=$('#hover-tooltip');if(!tipAnchor?.isConnected||!box||box.hidden){hideTooltip();return;}const r=tipAnchor.getBoundingClientRect(),gap=12,pad=12,w=box.offsetWidth,h=box.offsetHeight,vw=document.documentElement.clientWidth,vh=window.innerHeight;let x=r.left+r.width/2-w/2,y=r.top-h-gap;if(tipAnchor.matches('[data-tooltip-trait],[data-tooltip-special]')&&r.right+w+gap<vw-pad){x=r.right+gap;y=r.top;}else if(y<pad)y=r.bottom+gap;box.style.left=Math.max(pad,Math.min(x,vw-w-pad))+'px';box.style.top=Math.max(pad,Math.min(y,vh-h-pad))+'px';}
function showTooltip(anchor,focusTarget){if(!anchor?.isConnected)return;hideTooltip();tipAnchor=anchor;const box=tooltipBox();if(anchor.dataset.tooltipTile)box.innerHTML=tileTip(JSON.parse(anchor.dataset.tooltipTile));else if(anchor.dataset.tooltipTrait)box.innerHTML=traitTip(anchor.dataset.tooltipTrait);else box.innerHTML=specialTip(JSON.parse(anchor.dataset.tooltipSpecial));if(!box.innerHTML){hideTooltip();return;}box.hidden=false;if(focusTarget){tipFocus=focusTarget;focusTarget.setAttribute('aria-describedby','hover-tooltip');}positionTooltip();}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const anchor=tooltipTarget(e.target);if(!anchor||anchor===tipAnchor)return;clearTimeout(tipOpenTimer);clearTimeout(tipCloseTimer);if(tipAnchor&&$('#hover-tooltip')&&!$('#hover-tooltip').hidden)showTooltip(anchor);else tipOpenTimer=setTimeout(()=>showTooltip(anchor),160);});
document.addEventListener('pointerout',e=>{const anchor=tooltipTarget(e.target);if(anchor?.contains(e.relatedTarget))return;clearTimeout(tipOpenTimer);if(tipAnchor)tipCloseTimer=setTimeout(()=>{const box=$('#hover-tooltip');if(!box?.matches(':hover'))hideTooltip();},100);});
document.addEventListener('focusin',e=>{if(!e.target.matches?.(':focus-visible'))return;const anchor=tooltipTarget(e.target,true);if(anchor)showTooltip(anchor,e.target);});
document.addEventListener('focusout',()=>hideTooltip());
document.addEventListener('pointerdown',()=>hideTooltip(),true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#hover-tooltip')&&!$('#hover-tooltip').hidden){hideTooltip();e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('scroll',e=>{if(!$('#hover-tooltip')?.contains(e.target))hideTooltip();},true);
window.addEventListener('resize',()=>hideTooltip());

accountUI=mountLocalAccountUI(account,{onToast:toast,restore:raw=>{
 game=raw?Game.restore(raw):new Game();ui.modal=null;ui.scoring=null;ui.push=null;ui.discard.clear();ui.shopHidden=false;ui.round=game.round;render();
}});
// Touch has no hover. A stationary long press opens the same effect description.
let touchHold=null,touchTipUntil=0;
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;const anchor=tooltipTarget(e.target);if(!anchor)return;const hold={x:e.clientX,y:e.clientY,pointer:e.pointerId};touchHold=hold;hold.timer=setTimeout(()=>{if(touchHold!==hold||handDrag?.moved)return;showTooltip(anchor);touchTipUntil=performance.now()+1000;hold.shown=true;},500);},{passive:true});
document.addEventListener('pointermove',e=>{if(touchHold&&Math.hypot(e.clientX-touchHold.x,e.clientY-touchHold.y)>8){clearTimeout(touchHold.timer);touchHold=null;}},{passive:true});
for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>{if(touchHold?.shown)touchTipUntil=performance.now()+700;clearTimeout(touchHold?.timer);touchHold=null;},{passive:true});
document.addEventListener('click',e=>{if(performance.now()<touchTipUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
window.addEventListener('beforeunload',save);
render();account.boot();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{const activate=()=>reg.waiting?.postMessage({type:'ACTIVATE_UPDATE'});activate();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',activate);});reg.update().catch(()=>{});}).catch(()=>{});
